function processOrder(order) {
  const subtotal = order.items.reduce((s, i) => s + i.price, 0);
  const tax = Math.round(subtotal * 0.0875 * 100) / 100;
  const total = subtotal + tax;
  analytics.track('order_processed', { orderId: order.id, total });
  const receipt = `Order ${order.id}: subtotal ${subtotal}, tax ${tax}, total ${total}`;
  email.send(order.email, receipt);
}

function saveUserProfile(user, notify) {
  const rows = db.query(`SELECT * FROM users WHERE id=${user.id}`);
  if (rows.length === 0) {
    db.insert('users', user);
  } else {
    db.update('users', user);
  }
  if (notify) {
    const message = `User ${user.name} updated at ${new Date().toISOString()}`;
    email.send(user.email, message);
  }
}

